#!/usr/bin/env python3
import os
import sys
import subprocess
import json
from typing import Dict, List, Any
from anthropic import Anthropic

class BashTool:
    def __init__(self):
        self.name = "run_bash"
        self.description = "Execute bash commands"

    def execute(self, command: str) -> Dict[str, Any]:
        try:
            result = subprocess.run(
                command,
                shell=True,
                capture_output=True,
                text=True,
                timeout=30
            )
